def free_disposal_present(spans):
    for span in spans:
        raw = span.get('text', '')
        text = low(raw)
        action = has_any(text, ['return', 'destroy', 'destruction', 'delete', 'erase'])
        material = has_any(text, ['confidential information', 'such information', 'information disclosed', 'all information', 'copy', 'copies', 'reproduction', 'materials', 'documents', 'files', 'records'])
        if action and material and 'return receipt requested' not in text:
            return True
    return False

def free_post_disposal_retention_present(spans):
    for span in spans:
        text = low(span.get('text', ''))
        if has_any(text, ['without retaining', 'no copy shall be retained', 'no copies or records thereof shall be retained', 'may retain', 'may be retained', 'entitled to retain', 'permitted to retain', 'not be required to delete', 'will not be required to delete']):
            return True
        if 'single copy' in text and 'retain' in text:
            return True
        if has_any(text, ['back-up', 'backup', 'archive']) and has_any(text, ['retain', 'retained', 'delete', 'destroy']):
            return True
    return False

def free_internal_permission_present(spans):
    for span in spans:
        text = low(span.get('text', ''))
        roles = has_any(text, ['employee', 'staff', 'personnel', 'consultant', 'contractor', 'agent', 'representative', 'adviser', 'advisor'])
        effect = has_any(text, ['may disclose', 'may be disclosed', 'restrict disclosure', 'restrict access', 'will disclose information', 'except in confidence', 'except its employees', 'disclosed only to'])
        if roles and effect and 'confidential information' in text:
            return True
    return False

def free_elliptical_permission(raw, uid, statements):
    text = low(raw)
    if not ('obligations of the parties' in text and 'need to know' in text and 'confidential information' in text):
        return False
    recipients = []
    if 'employee' in text:
        recipients.append(['employees_of', ['receiving_party']])
    if 'agent' in text:
        recipients.append(['agents_of', ['receiving_party']])
    if 'representative' in text:
        recipients.append(['representatives_of', ['receiving_party']])
    if not recipients:
        return False
    add_statement(statements, ['source_elliptical_clause', raw], [uid])
    add_statement(statements, ['permission', ['receiving_party'], ['disclose', ['confidential_information'], make_union(recipients)], ['need_to_know', raw]], [uid])
    return True

def apply(inputs, premises):
    source_output = inputs.get('source_output', {})
    statements = []
    unresolved = []
    complete = False
    if isinstance(source_output, dict):
        complete = bool(source_output.get('complete', False))
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                statements.append({'term': row.get('term'), 'support_ids': list(row.get('support_ids', []))})
        for item in source_output.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    spans = []
    all_ids = []
    elliptical = False
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
            all_ids.append(span.get('id'))
    for span in spans:
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        if free_elliptical_permission(raw, uid, statements):
            elliptical = True
        free_add_disposal_repairs(raw, uid, statements)
